// HasAlertInvestigation applies the HasEdge predicate on the "alert_investigation" edge.
func HasAlertInvestigation() predicate.AlertInvestigationEvent {
	return predicate.AlertInvestigationEvent(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AlertInvestigationTable, AlertInvestigationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAlertInvestigationWith applies the HasEdge predicate on the "alert_investigation" edge with a given conditions (other predicates).
func HasAlertInvestigationWith(preds ...predicate.AlertInvestigation) predicate.AlertInvestigationEvent {
	return predicate.AlertInvestigationEvent(func(s *sql.Selector) {
		step := newAlertInvestigationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

